using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SharpenFinEffect", menuName = "Data/Battle/Effects/Cellarius/SharpenFin Effect")]
public class SharpenFinEffect : Effect
{
	[Header("Sharpen Fin Action")]
	[SerializeField]
	private SharpenFinAction sharpenFinAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string arg = sharpenFinAction.EmpowerAction.GetActionDescription(1).LowercaseFirst().RemoveLast();
		return Smart.Format(GetLocalizedDescription(), sharpenFinAction.SharpenFinAmountToTrigger, arg, base.localizationManager.GetLocalizedLoseAllEffect(sharpenFinAction.SharpenFinEffect).LowercaseFirst());
	}
}
